#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill; its library is scripts/lib/wizard.sh.

set -euo pipefail

# shellcheck source=lib/wizard.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/wizard.sh"

# ──────────────────────────────────────────────────────────────────────────
# STAGES: one stage() per step the human takes. TOTAL_STAGES matches them.
# ──────────────────────────────────────────────────────────────────────────



# Google Sign-In setup for PlantAí (ticket #36): recreates from scratch the
# Google Cloud project, the consent screen and the three OAuth clients (Android
# release, Android debug, Web), then writes GOOGLE_WEB_CLIENT_ID to api/.env.
# The Web client secret is never stored: the API only checks the audience.
# Usage: scripts/google-oauth-wizard.sh

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$ROOT/api/.env"

PACKAGE_NAME="dev.angelobez.plantai"
DEBUG_KEYSTORE="${DEBUG_KEYSTORE:-$HOME/.android/debug.keystore}"
RELEASE_KEYSTORE="${RELEASE_KEYSTORE:-$HOME/.config/plantai/upload-keystore.jks}"
KEY_PROPERTIES="${KEY_PROPERTIES:-$HOME/.config/plantai/key.properties}"

# prop KEY: value of KEY in KEY_PROPERTIES (CR stripped), empty if missing.
prop() {
  [[ -f "$KEY_PROPERTIES" ]] || return 0
  { grep -E "^${1}=" "$KEY_PROPERTIES" || true; } | tail -n1 | cut -d= -f2- | tr -d '\r'
}

# sha1_of KEYSTORE [ALIAS]: SHA-1 of the certificate, read with keytool. The
# store password comes from $KEYSTORE_PASS via -storepass:env, so it never
# shows up on screen or in the process list.
sha1_of() {
  local keystore="$1" alias="${2:-}" args
  args=(-list -v -keystore "$keystore" -storepass:env KEYSTORE_PASS)
  [[ -n "$alias" ]] && args+=(-alias "$alias")
  { keytool "${args[@]}" 2>/dev/null || true; } | awk '/SHA1:/ { print $2; exit }'
}

TOTAL_STAGES=6

banner "PlantAí · Login com Google (projeto, consentimento e clientes OAuth)"

# ── 1. SHA-1 fingerprints ────────────────────────────────────────────────
stage "Impressões digitais SHA-1 das chaves Android"
say "Os dois clientes Android precisam do SHA-1 da chave que assina o APK."
say "Vou ler as duas chaves com o keytool (nada é aberto no navegador)."
printf '\n'

if ! command -v keytool >/dev/null 2>&1; then
  warn "keytool não encontrado. Instale um JDK (o do Android Studio serve) e rode de novo."
  exit 1
fi

SHA1_DEBUG=""
if [[ -f "$DEBUG_KEYSTORE" ]]; then
  SHA1_DEBUG=$(KEYSTORE_PASS=android sha1_of "$DEBUG_KEYSTORE" androiddebugkey)
fi
if [[ -z "$SHA1_DEBUG" ]]; then
  warn "não consegui ler $DEBUG_KEYSTORE."
  note "  Ele é criado no primeiro 'flutter run'; rode o app uma vez em debug e volte aqui."
  exit 1
fi
printf '  %s✓ debug%s   %s\n' "$GREEN" "$RESET" "$SHA1_DEBUG"
note "  $DEBUG_KEYSTORE"

SHA1_RELEASE=""
RELEASE_PASS=$(prop storePassword)
RELEASE_ALIAS=$(prop keyAlias)
if [[ -f "$RELEASE_KEYSTORE" && -n "$RELEASE_PASS" ]]; then
  SHA1_RELEASE=$(KEYSTORE_PASS="$RELEASE_PASS" sha1_of "$RELEASE_KEYSTORE" "$RELEASE_ALIAS")
fi
unset RELEASE_PASS
if [[ -z "$SHA1_RELEASE" ]]; then
  warn "não consegui ler $RELEASE_KEYSTORE."
  note "  Confira se o .jks existe e se $KEY_PROPERTIES tem storePassword (e keyAlias)."
  note "  Para criar a chave de upload, veja 'Release signing' no README."
  exit 1
fi
printf '  %s✓ release%s %s\n' "$GREEN" "$RESET" "$SHA1_RELEASE"
note "  $RELEASE_KEYSTORE"
printf '\n'
note "Os dois valores aparecem de novo nas etapas dos clientes Android."
pause "Enter para continuar"

# ── 2. Project ───────────────────────────────────────────────────────────
stage "Projeto no Google Cloud"
say "Crie um projeto só para o PlantAí (ou pule a criação se ele já existe)."
open_url "https://console.cloud.google.com/projectcreate"
step "Nome do projeto: PlantAi"
step "Local / organização: Sem organização"
step "Clique em Criar e espere a notificação de projeto pronto."
step "Copie o ID do projeto (ex.: plantai-513101), que aparece abaixo do nome."
note "  Se o projeto já existe, o ID está no seletor de projetos, no topo do console."
printf '\n'
PROJECT_ID=""
while [[ -z "$PROJECT_ID" ]]; do
  printf '  %sCole o ID do projeto:%s ' "$BOLD" "$RESET"
  read -r PROJECT_ID || true
  PROJECT_ID="${PROJECT_ID//[[:space:]]/}"
done
printf '  %s✓ projeto%s %s\n' "$GREEN" "$RESET" "$PROJECT_ID"
pause "Enter para continuar"

# ── 3. Consent screen ────────────────────────────────────────────────────
stage "Tela de consentimento (Google Auth Platform)"
say "Configure o app que aparece na tela 'Fazer login com o Google'."
open_url "https://console.cloud.google.com/auth/overview?project=${PROJECT_ID}"
step "Clique em Começar (Get started)."
step "Informações do app: nome PlantAí; e-mail de suporte: a sua conta Google."
step "Público (Audience): Externo (External)."
step "Dados de contato: o seu e-mail. Aceite a política de dados de usuário e clique em Criar."
pause "Enter quando a configuração estiver criada"
printf '\n'
say "Agora o usuário de teste: com o app em Testando, só ele consegue entrar."
open_url "https://console.cloud.google.com/auth/audience?project=${PROJECT_ID}"
step "Confira que o status de publicação é Testando (Testing). Não publique o app."
step "Em Usuários de teste, clique em Add users, adicione a sua conta Google e salve."
pause "Enter quando o usuário de teste estiver salvo"

# ── 4. Android client (release) ──────────────────────────────────────────
stage "Cliente OAuth Android (release)"
say "Este cliente vale para o APK assinado com a chave de upload."
open_url "https://console.cloud.google.com/auth/clients/create?project=${PROJECT_ID}"
step "Tipo de aplicativo: Android"
step "Nome: PlantAí Android (release)"
step "Nome do pacote: ${PACKAGE_NAME}"
step "Impressão digital do certificado SHA-1: ${SHA1_RELEASE}"
step "Clique em Criar. Não precisa copiar nada: o app não usa o ID deste cliente."
pause "Enter quando o cliente release estiver criado"

# ── 5. Android client (debug) ────────────────────────────────────────────
stage "Cliente OAuth Android (debug)"
say "O mesmo, para o 'flutter run' assinado com a chave de debug."
open_url "https://console.cloud.google.com/auth/clients/create?project=${PROJECT_ID}"
step "Tipo de aplicativo: Android"
step "Nome: PlantAí Android (debug)"
step "Nome do pacote: ${PACKAGE_NAME}"
step "Impressão digital do certificado SHA-1: ${SHA1_DEBUG}"
step "Clique em Criar."
pause "Enter quando o cliente debug estiver criado"

# ── 6. Web client → api/.env ─────────────────────────────────────────────
stage "Cliente OAuth Web (API)"
say "A API confere se o token do Google foi emitido para este cliente (audience)."
open_url "https://console.cloud.google.com/auth/clients/create?project=${PROJECT_ID}"
step "Tipo de aplicativo: Aplicativo da Web"
step "Nome: PlantAí Web (API)"
step "Deixe Origens JavaScript autorizadas e URIs de redirecionamento vazios."
step "Clique em Criar e copie o ID do cliente (termina em .apps.googleusercontent.com)."
warn "Não baixe o JSON nem copie a chave secreta: ela não é usada nem guardada."
printf '\n'
GOOGLE_WEB_CLIENT_ID=""
while true; do
  ask GOOGLE_WEB_CLIENT_ID "Cole o ID do cliente Web:"
  GOOGLE_WEB_CLIENT_ID="${GOOGLE_WEB_CLIENT_ID//[[:space:]]/}"
  [[ "$GOOGLE_WEB_CLIENT_ID" == *.apps.googleusercontent.com ]] && break
  warn "isso não parece um ID de cliente (deveria terminar em .apps.googleusercontent.com)."
done
write_env GOOGLE_WEB_CLIENT_ID "$GOOGLE_WEB_CLIENT_ID"
printf '\n'
note "O mesmo ID é o GOOGLE_SERVER_CLIENT_ID do app (ver o README)."
pause "Enter para terminar"

finish
note "Projeto ${PROJECT_ID}: consentimento em Testando, clientes Android (release e debug) e Web."
note "Reinicie a API para ela ler o GOOGLE_WEB_CLIENT_ID novo."
printf '\n'
